using System.Net;
using System.Text;
using System.Text.Json;
using PaymentAuthorization.Domain;
using PaymentAuthorization.Infrastructure;

namespace PaymentAuthorization.IntegrationTest.PaymentGateway;

/// <summary>
/// Contract coverage for <see cref="HttpPaymentGateway"/>: proves the request we build matches
/// what the provider expects, and that every response shape the provider can send back
/// (approved, declined, and the 402 refusal) is translated into the right outcome.
/// </summary>
public sealed class HttpPaymentGatewayTests
{
    [Fact]
    public async Task Sends_the_reference_amount_and_currency_the_provider_expects()
    {
        var handler = new StubHttpMessageHandler(_ =>
            JsonResponse(HttpStatusCode.OK, """{"status":"approved"}"""));
        var sut = CreateGateway(handler);

        await sut.AuthorizeAsync("ORD-42", new Money(19.99m, "eur"), CancellationToken.None);

        var request = Assert.Single(handler.Requests);
        Assert.Equal(HttpMethod.Post, request.Method);
        Assert.Equal("/v1/authorizations", request.RequestUri!.PathAndQuery);

        using var body = JsonDocument.Parse(request.Body);
        Assert.Equal("ORD-42", body.RootElement.GetProperty("reference").GetString());
        Assert.Equal(19.99m, body.RootElement.GetProperty("amount").GetDecimal());
        Assert.Equal("EUR", body.RootElement.GetProperty("currency").GetString());
    }

    [Fact]
    public async Task A_200_response_with_status_approved_is_read_back_as_Approved()
    {
        var handler = new StubHttpMessageHandler(_ =>
            JsonResponse(HttpStatusCode.OK, """{"status":"approved"}"""));
        var sut = CreateGateway(handler);

        var outcome = await sut.AuthorizeAsync("ORD-1", new Money(10m, "USD"), CancellationToken.None);

        Assert.Equal(AuthorizationOutcome.Approved, outcome);
    }

    [Fact]
    public async Task A_200_response_with_status_declined_is_read_back_as_Declined()
    {
        var handler = new StubHttpMessageHandler(_ =>
            JsonResponse(HttpStatusCode.OK, """{"status":"declined"}"""));
        var sut = CreateGateway(handler);

        var outcome = await sut.AuthorizeAsync("ORD-2", new Money(10m, "USD"), CancellationToken.None);

        Assert.Equal(AuthorizationOutcome.Declined, outcome);
    }

    [Fact]
    public async Task A_402_response_from_the_provider_is_read_back_as_Declined()
    {
        var handler = new StubHttpMessageHandler(_ =>
            new HttpResponseMessage(HttpStatusCode.PaymentRequired));
        var sut = CreateGateway(handler);

        var outcome = await sut.AuthorizeAsync("ORD-3", new Money(10m, "USD"), CancellationToken.None);

        Assert.Equal(AuthorizationOutcome.Declined, outcome);
    }

    [Fact]
    public async Task An_unexpected_error_status_from_the_provider_surfaces_as_a_failure()
    {
        var handler = new StubHttpMessageHandler(_ => new HttpResponseMessage(HttpStatusCode.InternalServerError));
        var sut = CreateGateway(handler);

        await Assert.ThrowsAsync<HttpRequestException>(
            () => sut.AuthorizeAsync("ORD-4", new Money(10m, "USD"), CancellationToken.None));
    }

    private static Infrastructure.HttpPaymentGateway CreateGateway(HttpMessageHandler handler)
    {
        var client = new HttpClient(handler) { BaseAddress = new Uri("https://provider.example") };
        return new Infrastructure.HttpPaymentGateway(client);
    }

    private static HttpResponseMessage JsonResponse(HttpStatusCode status, string json) =>
        new(status) { Content = new StringContent(json, Encoding.UTF8, "application/json") };

    /// <summary>Captures every request sent by the gateway and answers with a canned response,
    /// standing in for the provider's REST API.</summary>
    private sealed class StubHttpMessageHandler(Func<CapturedRequest, HttpResponseMessage> respond) : HttpMessageHandler
    {
        public List<CapturedRequest> Requests { get; } = [];

        protected override async Task<HttpResponseMessage> SendAsync(
            HttpRequestMessage request, CancellationToken cancellationToken)
        {
            var body = request.Content is null
                ? string.Empty
                : await request.Content.ReadAsStringAsync(cancellationToken);
            var captured = new CapturedRequest(request.Method, request.RequestUri!, body);
            Requests.Add(captured);
            return respond(captured);
        }
    }

    private sealed record CapturedRequest(HttpMethod Method, Uri RequestUri, string Body);
}

